// Turns a web form, WhatsApp or webhook message into one standard lead.
const leads = [];
const now = new Date().toISOString();
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());

for (const item of $input.all()) {
  const j = item.json;

  // 1) WhatsApp Cloud API event (from the WhatsApp Trigger)
  if (Array.isArray(j.messages)) {
    const names = Object.fromEntries((j.contacts || []).map(c => [c.wa_id, c.profile?.name || '']));
    for (const m of j.messages) {
      if (m.type !== 'text') continue; // v0.1 reads text only; photos and voice notes go to the owner later
      leads.push({
        channel: 'whatsapp',
        customer_name: clean(names[m.from]),
        customer_email: '',
        customer_phone: '+' + clean(m.from),
        followup_consent: false,
        car_text: '',
        request_text: clean(m.text?.body),
        received_at: m.timestamp ? new Date(Number(m.timestamp) * 1000).toISOString() : now,
      });
    }
    continue;
  }

  // 2) n8n web form
  if (j.formMode !== undefined || j.submittedAt !== undefined) {
    leads.push({
      channel: 'web_form',
      customer_name: clean(j.name),
      customer_email: clean(j.email).toLowerCase(),
      customer_phone: clean(j.phone),
      followup_consent: (() => { let c = j.consent; if (typeof c === 'string' && c.startsWith('[')) { try { c = JSON.parse(c); } catch (e) {} } return Array.isArray(c) ? c.length > 0 : !!c; })(),
      car_text: clean(j.car),
      request_text: clean(j.request),
      received_at: now,
    });
    continue;
  }

  // 3) Generic webhook (website widget, email parser, other tools)
  const b = j.body || j;
  leads.push({
    channel: clean(b.channel) || 'webhook',
    customer_name: clean(b.name),
    customer_email: clean(b.email).toLowerCase(),
    customer_phone: clean(b.phone),
    followup_consent: b.consent === true || b.consent === 'true',
    car_text: clean(b.car),
    request_text: clean(b.request || b.message),
    received_at: now,
  });
}

return leads.filter(l => l.request_text).map(json => ({ json }));

// Gives the AI the customer's words plus the garage's list of priced jobs.
// Messages from the owner's own number (e.g. the daily "hi" that keeps WhatsApp's 24-hour window open) are not leads.
const digits = (v) => String(v || '').replace(/\D/g, '');
const owner = digits($('Load settings').first().json.owner_whatsapp_number);
const jobs = $('Load price book').all().map(i => i.json).filter(r => r.job_code);
const jobList = jobs.map(r => '- ' + r.job_code + ': ' + r.name + (r.keywords ? ' (also: ' + r.keywords + ')' : '')).join('\n');

return $('Normalise lead').all().filter(item => !(owner && item.json.channel === 'whatsapp' && digits(item.json.customer_phone) === owner)).map(item => ({
  json: {
    ...item.json,
    ai_text: 'PRICE LIST JOB CODES:\n' + jobList +
      '\n\nCAR (as typed by the customer, may be empty): ' + (item.json.car_text || '-') +
      '\n\nCUSTOMER MESSAGE:\n' + item.json.request_text,
  },
}));

