// Rules, not AI, decide the price and whether the quote can go out automatically.
const s = $('Load settings').first().json;
const book = Object.fromEntries($('Load price book').all().map(i => [i.json.job_code, i.json]));
const leads = $('Build AI request').all();
const ai = $input.all();
const threshold = Number(s.confidence_threshold);
const rate = Number(s.labour_rate_eur);
const vat = Number(s.vat_rate) / 100;
const premium = String(s.premium_brands || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
const roundDown = (x) => Math.floor(x / 5) * 5;
const roundUp = (x) => Math.ceil(x / 5) * 5;
const eur = (x) => '€' + x.toLocaleString('en-GB');

return leads.map((lead, i) => {
  const L = lead.json;
  const out = ai[i]?.json?.output;
  const reasons = [];
  if (!out) reasons.push('AI could not read the message');

  const x = out || {};
  const make = String(x.car_make || '').trim();
  const model = String(x.car_model || '').trim();
  const year = Number(x.car_year) || 0;
  const conf = Number(x.confidence) || 0;
  const requested = Array.isArray(x.jobs) ? x.jobs : [];
  const unmatched = (Array.isArray(x.unmatched_requests) ? x.unmatched_requests : []).map(String);

  // Map AI job codes to the price book. Unknown codes count as unmatched.
  const matched = [];
  for (const j of requested) {
    const row = book[j.job_code];
    if (row) { if (!matched.find(m => m.job_code === row.job_code)) matched.push(row); }
    else unmatched.push(j.customer_words || j.job_code);
  }

  if (out) {
    if (conf < threshold) reasons.push('AI confidence ' + conf.toFixed(2) + ' is below ' + threshold);
    if (x.safety_flag) reasons.push('Possible safety issue');
    if (x.symptoms_only && !matched.length) reasons.push('Symptoms only, needs diagnosis');
    if (!matched.length) reasons.push('No job matched the price book');
    if (unmatched.length) reasons.push('Not in price book: ' + unmatched.join('; '));
    for (const m of matched) if (!m.auto_quote) reasons.push(m.name + ' is set to owner-only pricing');
    if (!make || !model) reasons.push('Car make or model missing');
  }
  if (L.channel !== 'whatsapp' && !L.customer_email) reasons.push('No email to reply to');

  // Price: labour x rate (x premium multiplier) + parts range, plus VAT. Rounded to €5.
  const mult = premium.includes(make.toLowerCase()) ? Number(s.premium_multiplier) || 1 : 1;
  let low = 0, high = 0;
  const lines = matched.map(m => {
    const labour = Number(m.labour_hours) * rate * mult;
    const lo = roundDown((labour + Number(m.parts_low_eur)) * (1 + vat));
    const hi = roundUp((labour * 1.2 + Number(m.parts_high_eur) * mult) * (1 + vat));
    low += lo; high += hi;
    return { name: m.name, lo, hi };
  });

  const route = reasons.length ? 'owner_review' : 'auto';
  const leadId = 'L-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
  const token = Math.random().toString(36).slice(2, 12);
  const car = [make, model, year || ''].filter(Boolean).join(' ');
  const bookingLink = s.booking_form_url + (String(s.booking_form_url).includes('?') ? '&' : '?') + 'lead_id=' + encodeURIComponent(leadId) + '&token=' + token;
  const first = (L.customer_name || '').split(' ')[0];

  const quoteText = [
    'Hi' + (first ? ' ' + first : '') + ',',
    '',
    'Thanks for contacting ' + s.garage_name + '. Here is our estimate for your ' + (car || 'car') + ':',
    '',
    ...lines.map(l => '• ' + l.name + ': ' + eur(l.lo) + ' – ' + eur(l.hi)),
    '',
    'Estimated total: ' + eur(low) + ' – ' + eur(high) + ' (incl. ' + s.vat_rate + '% VAT).',
    'The final price is confirmed after we inspect the car. We will always ask you before doing any extra work.',
    '',
    'Book a time here: ' + bookingLink,
    'Or call us on ' + s.garage_phone + '.',
    '',
    s.garage_name,
  ].join('\n');

  return { json: {
    lead_id: leadId,
    token,
    received_at: L.received_at,
    channel: L.channel,
    customer_name: L.customer_name,
    customer_email: L.customer_email,
    customer_phone: L.customer_phone,
    followup_consent: L.followup_consent,
    request_text: L.request_text,
    language: String(x.language || ''),
    car_make: make,
    car_model: model,
    car_year: year,
    jobs_matched: matched.map(m => m.job_code).join(','),
    jobs_unmatched: unmatched.join('; '),
    ai_confidence: conf,
    ai_safety_flag: !!x.safety_flag,
    ai_summary: String(x.summary_en || ''),
    route,
    review_reasons: reasons.join(' | '),
    quote_low: low,
    quote_high: high,
    quote_lines: lines.map(l => l.name + ': ' + eur(l.lo) + ' – ' + eur(l.hi)).join('\n'),
    booking_link: bookingLink,
    status: route === 'auto' ? 'quoted' : 'awaiting_owner',
    reply_subject: 'Your estimate from ' + s.garage_name + (car ? ' – ' + car : ''),
    reply_text: route === 'auto' ? quoteText : '',
  } };
});

