  '',
  'They wrote: "' + t(j.request_text) + '"',
  '',
  'Why it was not sent automatically:',
  ...String(j.review_reasons).split(' | ').map(r => '- ' + t(r)),
  '',
  'Calculated estimate: ' + (j.quote_high ? '€' + j.quote_low + ' – €' + j.quote_high : 'none'),
  t(j.quote_lines || ''),
  '',
  'Lead ' + t(j.lead_id),
].join('\n');
})() }}

