// Turns the owner's answer (or no answer) into the customer message and new status.
const s = $('Load settings').first().json;
const eur = (x) => '€' + Number(x).toLocaleString('en-GB');

return $input.all().map((item, i) => {
  const lead = $('Price & route').itemMatching(i).json;
  // The response form returns answers keyed by field label.
  const r = item.json.data || {};
  const decision = String(r['Decision'] || '');
  const first = (lead.customer_name || '').split(' ')[0];
  const hi = 'Hi' + (first ? ' ' + first : '') + ',';
  const note = String(r['Note to the customer'] || '').trim();
  const low = Number(r['Your price from (€ incl. VAT)']) || Number(lead.quote_low) || 0;
  const high = Number(r['Your price to (€ incl. VAT)']) || Number(lead.quote_high) || 0;
  const car = [lead.car_make, lead.car_model, lead.car_year || ''].filter(Boolean).join(' ');

  let status, text, ownerFyi = '';
  if (decision.startsWith('Send estimate')) {
    status = 'quoted';
    const useOwner = decision.includes('my price');
    text = [hi, '',
      'Thanks for contacting ' + s.garage_name + '. Here is our estimate' + (car ? ' for your ' + car : '') + ':', '',
      ...(useOwner ? [] : String(lead.quote_lines || '').split('\n').filter(Boolean).map(l => '• ' + l)),
      'Estimated total: ' + eur(low) + ' – ' + eur(high) + ' (incl. ' + s.vat_rate + '% VAT).',
      ...(note ? ['', note] : []),
      '', 'The final price is confirmed after we inspect the car. We will always ask you before doing any extra work.',
      '', 'Book a time here: ' + lead.booking_link, 'Or call us on ' + s.garage_phone + '.', '', s.garage_name].join('\n');
  } else if (decision.startsWith('I will call')) {
    status = 'needs_call';
    text = [hi, '', 'Thanks for contacting ' + s.garage_name + '. We would like to ask you a couple of questions to give you an accurate price, so we will call you shortly' + (lead.customer_phone ? ' on ' + lead.customer_phone : '') + '.', ...(note ? ['', note] : []), '', s.garage_name].join('\n');
  } else if (decision.startsWith('Decline')) {
    status = 'declined';
    text = [hi, '', 'Thanks for contacting ' + s.garage_name + '. Unfortunately we cannot take on this job.', ...(note ? ['', note] : []), '', s.garage_name].join('\n');
  } else {
    // No answer in time: the customer still hears from us, and the owner gets a nudge.
    status = 'needs_call';
    text = [hi, '', 'Thanks for contacting ' + s.garage_name + '. A mechanic needs to look at your request, so we will get back to you personally' + (lead.customer_phone ? ' by phone (' + lead.customer_phone + ')' : '') + ' as soon as possible.', '', s.garage_name].join('\n');
    ownerFyi = 'No decision within the time limit, so the customer got a holding message. Please call them: ' + (lead.customer_name || '') + ' ' + (lead.customer_phone || lead.customer_email || '') + ' (lead ' + lead.lead_id + ').';
  }

  return { json: {
    ...lead,
    status,
    quote_low: status === 'quoted' ? low : lead.quote_low,
    quote_high: status === 'quoted' ? high : lead.quote_high,
    owner_decision: decision || 'no answer (timed out)',
    owner_note: note,
    reply_text: text,
    owner_fyi: ownerFyi,
  } };
});

// Decides how the reply goes out and when the first follow-up is due.
const s = $('Load settings').first().json;
return $input.all().map((item, idx) => {
  const j = { ...$('Price & route').itemMatching(idx).json, ...item.json };
  const via = j.channel === 'whatsapp' ? 'whatsapp' : (j.customer_email ? 'email' : 'none');
  // WhatsApp: one reminder inside the 24-hour customer service window, timed from the customer's message.
  // Email: reminders only with consent.
  let next = null;
  if (j.status === 'quoted') {
    const h = Number(s.followup_hours) || 20;
    if (via === 'whatsapp') next = new Date(new Date(j.received_at).getTime() + Math.min(h, 23) * 3600e3).toISOString();
    else if (via === 'email' && j.followup_consent) next = new Date(Date.now() + h * 3600e3).toISOString();
  }
  const fyi = j.owner_fyi !== undefined ? j.owner_fyi : (j.route === 'auto'
    ? 'Estimate sent automatically to ' + (j.customer_name || 'a customer') + ' via ' + via + ': ' + [j.car_make, j.car_model].filter(Boolean).join(' ') + ', €' + j.quote_low + ' – €' + j.quote_high + ' (lead ' + j.lead_id + ').'
    : '');
  return { json: { ...j, reply_via: via, next_followup_at: next, owner_fyi: fyi } };
});
